from seqkit import unique


def test_unique_preserves_first_seen_order():
    assert unique(['b', 'a', 'b', 'c', 'a']) == ['b', 'a', 'c']


def test_unique_supports_unhashable_dicts():
    first = {'id': 1, 'name': 'first'}
    duplicate = {'id': 1, 'name': 'first'}
    second = {'id': 2, 'name': 'second'}
    assert unique([first, duplicate, second, first]) == [first, second]


def test_unique_does_not_mutate_input():
    values = ['b', 'a', 'b']
    assert unique(values) == ['b', 'a']
    assert values == ['b', 'a', 'b']
